module maze_solver (\n    input clk, rst_n, start,\n    input [3:0] n, m,\n    input [5:0] k,\n    input [1:0] grid_in [0:7][0:7],\n    output reg [1:0] grid_out [0:7][0:7],\n    output reg done\n);\n\n    // State definitions\n    localparam [3:0]\n        IDLE        = 4'd0,\n        INIT_SCAN   = 4'd1,\n        SCAN        = 4'd2,\n        BFS_INIT    = 4'd3,\n        BFS_LOOP    = 4'd4,\n        BFS_DEQUEUE = 4'd5,\n        BFS_PROCESS = 4'd6,\n        BFS_ENQUEUE = 4'd7,\n        MARK        = 4'd8,\n        MARK_LOOP   = 4'd9,\n        DONE        = 4'd10;\n\n    reg [3:0] state;\n    reg [2:0] row_idx, col_idx;\n    reg [5:0] s, target, visited_count;\n    reg found_start;\n    reg [2:0] start_row, start_col;\n    reg [2:0] cur_row, cur_col;\n    reg [1:0] neighbor_count;\n    reg [0:7] visited [0:7];\n    reg [0:7] in_queue [0:7];\n    reg [5:0] queue [0:63];\n    reg [5:0] head, tail;\n    integer i, j;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            row_idx <= 3'd0;\n            col_idx <= 3'd0;\n            s <= 6'd0;\n            found_start <= 1'b0;\n            start_row <= 3'd0;\n            start_col <= 3'd0;\n            cur_row <= 3'd0;\n            cur_col <= 3'd0;\n            visited_count <= 6'd0;\n            neighbor_count <= 2'd0;\n            head <= 6'd0;\n            tail <= 6'd0;\n            \n            // Initialize arrays\n            for (i = 0; i < 8; i = i + 1) begin\n                visited[i] <= 8'd0;\n                in_queue[i] <= 8'd0;\n                for (j = 0; j < 8; j = j + 1) begin\n                    grid_out[i][j] <= 2'd0;\n                end\n            end\n            \n            for (i = 0; i < 64; i = i + 1) begin\n                queue[i] <= 6'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= INIT_SCAN;\n                    end\n                end\n                \n                INIT_SCAN: begin\n                    row_idx <= 3'd0;\n                    col_idx <= 3'd0;\n                    s <= 6'd0;\n                    found_start <= 1'b0;\n                    state <= SCAN;\n                end\n                \n                SCAN: begin\n                    if (grid_in[row_idx][col_idx] == 2'd1) begin\n                        s <= s + 6'd1;\n                        if (!found_start) begin\n                            start_row <= row_idx;\n                            start_col <= col_idx;\n                            found_start <= 1'b1;\n                        end\n                    end\n                    \n                    if (row_idx == (n - 4'd1) && col_idx == (m - 4'd1)) begin\n                        state <= BFS_INIT;\n                    end else begin\n                        if (col_idx == (m - 4'd1)) begin\n                            col_idx <= 3'd0;\n                            row_idx <= row_idx + 3'd1;\n                        end else begin\n                            col_idx <= col_idx + 3'd1;\n                        end\n                        state <= SCAN;\n                    end\n                end\n                \n                BFS_INIT: begin\n                    visited_count <= 6'd0;\n                    head <= 6'd0;\n                    tail <= 6'd0;\n                    target <= (s > k) ? (s - k) : 6'd0;\n                    \n                    // Clear visited and queue arrays\n                    for (i = 0; i < 8; i = i + 1) begin\n                        visited[i] <= 8'd0;\n                        in_queue[i] <= 8'd0;\n                    end\n                    \n                    if (found_start && (target > 6'd0)) begin\n                        queue[0] <= {start_row, start_col};\n                        tail <= 6'd1;\n                        in_queue[start_row][start_col] <= 1'b1;\n                    end\n                    state <= BFS_LOOP;\n                end\n                \n                BFS_LOOP: begin\n                    if (visited_count == target) begin\n                        state <= MARK;\n                    end else if (head == tail) begin\n                        state <= MARK;\n                    end else begin\n                        state <= BFS_DEQUEUE;\n                    end\n                end\n                \n                BFS_DEQUEUE: begin\n                    cur_row <= queue[head][5:3];\n                    cur_col <= queue[head][2:0];\n                    head <= head + 6'd1;\n                    state <= BFS_PROCESS;\n                end\n                \n                BFS_PROCESS: begin\n                    if (!visited[cur_row][cur_col]) begin\n                        visited[cur_row] <= visited[cur_row] | (8'd1 << cur_col);\n                        visited_count <= visited_count + 6'd1;\n                    end\n                    neighbor_count <= 2'd0;\n                    state <= BFS_ENQUEUE;\n                end\n                \n                BFS_ENQUEUE: begin\n                    case (neighbor_count)\n                        2'd0: begin  // Check down\n                            if (cur_row < (n - 4'd1) && \n                                grid_in[cur_row + 3'd1][cur_col] == 2'd1 && \n                                !visited[cur_row + 3'd1][cur_col] && \n                                !in_queue[cur_row + 3'd1][cur_col]) begin\n                                queue[tail] <= {cur_row + 3'd1, cur_col};\n                                tail <= tail + 6'd1;\n                                in_queue[cur_row + 3'd1] <= in_queue[cur_row + 3'd1] | (8'd1 << cur_col);\n                            end\n                        end\n                        \n                        2'd1: begin  // Check up\n                            if (cur_row > 3'd0 && \n                                grid_in[cur_row - 3'd1][cur_col] == 2'd1 && \n                                !visited[cur_row - 3'd1][cur_col] && \n                                !in_queue[cur_row - 3'd1][cur_col]) begin\n                                queue[tail] <= {cur_row - 3'd1, cur_col};\n                                tail <= tail + 6'd1;\n                                in_queue[cur_row - 3'd1] <= in_queue[cur_row - 3'd1] | (8'd1 << cur_col);\n                            end\n                        end\n                        \n                        2'd2: begin  // Check right\n                            if (cur_col < (m - 4'd1) && \n                                grid_in[cur_row][cur_col + 3'd1] == 2'd1 && \n                                !visited[cur_row][cur_col + 3'd1] && \n                                !in_queue[cur_row][cur_col + 3'd1]) begin\n                                queue[tail] <= {cur_row, cur_col + 3'd1};\n                                tail <= tail + 6'd1;\n                                in_queue[cur_row] <= in_queue[cur_row] | (8'd1 << (cur_col + 3'd1));\n                            end\n                        end\n                        \n                        2'd3: begin  // Check left\n                            if (cur_col > 3'd0 && \n                                grid_in[cur_row][cur_col - 3'd1] == 2'd1 && \n                                !visited[cur_row][cur_col - 3'd1] && \n                                !in_queue[cur_row][cur_col - 3'd1]) begin\n                                queue[tail] <= {cur_row, cur_col - 3'd1};\n                                tail <= tail + 6'd1;\n                                in_queue[cur_row] <= in_queue[cur_row] | (8'd1 << (cur_col - 3'd1));\n                            end\n                        end\n                    endcase\n                    \n                    if (neighbor_count == 2'd3) begin\n                        state <= BFS_LOOP;\n                    end else begin\n                        neighbor_count <= neighbor_count + 2'd1;\n                        state <= BFS_ENQUEUE;\n                    end\n                end\n                \n                MARK: begin\n                    row_idx <= 3'd0;\n                    col_idx <= 3'd0;\n                    state <= MARK_LOOP;\n                end\n                \n                MARK_LOOP: begin\n                    if (grid_in[row_idx][col_idx] == 2'd1 && !visited[row_idx][col_idx]) begin\n                        grid_out[row_idx][col_idx] <= 2'd2;\n                    end else begin\n                        grid_out[row_idx][col_idx] <= grid_in[row_idx][col_idx];\n                    end\n                    \n                    if (row_idx == (n - 4'd1) && col_idx == (m - 4'd1)) begin\n                        state <= DONE;\n                    end else begin\n                        if (col_idx == (m - 4'd1)) begin\n                            col_idx <= 3'd0;\n                            row_idx <= row_idx + 3'd1;\n                        end else begin\n                            col_idx <= col_idx + 3'd1;\n                        end\n                        state <= MARK_LOOP;\n                    end\n                end\n                \n                DONE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule